-- Disposable local verification only; entire fixture is rolled back.
BEGIN;
DO $$ DECLARE actor uuid:=gen_random_uuid();sess text:=gen_random_uuid()::text;cookie text:=repeat('g',43);slot jsonb;owner uuid:=gen_random_uuid();photo uuid;version uuid;result jsonb;content uuid:=gen_random_uuid();rev uuid:=gen_random_uuid();release uuid:=gen_random_uuid();
BEGIN
 IF NOT EXISTS(SELECT 1 FROM farm_private.schema_migrations sm WHERE sm.version='202611210013_media_metadata') THEN RAISE EXCEPTION 'Migration 013 required.';END IF;
 IF has_function_privilege('anon','public.farm_media_metadata_read(uuid)','EXECUTE') OR has_function_privilege('service_role','public.farm_media_metadata_save(uuid,integer,jsonb)','EXECUTE') THEN RAISE EXCEPTION 'FAIL: metadata RPC roles.';END IF;
 IF NOT has_function_privilege('authenticated','public.farm_media_metadata_save(uuid,integer,jsonb)','EXECUTE') THEN RAISE EXCEPTION 'FAIL: authenticated RPC unavailable.';END IF;
 INSERT INTO auth.users(id,email) VALUES(actor,'media-metadata-'||actor||'@example.test');
 INSERT INTO farm_private.memberships(user_id,state) VALUES(actor,'active');
 PERFORM public.farm_session_open(actor,sess,cookie,'sealed-fixture',repeat('h',43));
 slot:=public.farm_media_reserve(cookie,'image/png',1200);photo:=(slot->>'media_id')::uuid;version:=(slot->>'version_id')::uuid;
 PERFORM public.farm_media_claim(cookie,(slot->>'id')::uuid,owner);
 PERFORM public.farm_media_ready(cookie,(slot->>'id')::uuid,owner,800,600,'image/webp',900,repeat('a',64));
 PERFORM set_config('request.jwt.claim.sub',actor::text,true);PERFORM set_config('request.jwt.claims',jsonb_build_object('session_id',sess)::text,true);
 result:=public.farm_media_metadata_save(photo,1,'{"displayName":"Seedlings","altText":"Seedling tray","source":"https://example.test/photo","focalPoint":{"x":0.4,"y":0.5},"tags":["seedlings"]}');
 IF result->>'revision'<>'2' OR result#>>'{technical,width}'<>'800' OR result#>>'{editorial,displayName}'<>'Seedlings' THEN RAISE EXCEPTION 'FAIL: metadata CAS/technical preservation.';END IF;
 BEGIN PERFORM public.farm_media_metadata_save(photo,1,'{}');RAISE EXCEPTION 'FAIL: stale metadata accepted.';EXCEPTION WHEN SQLSTATE 'PT409' THEN NULL;END;
 BEGIN PERFORM public.farm_media_metadata_save(photo,2,'{"width":4}');RAISE EXCEPTION 'FAIL: technical overwrite accepted.';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 BEGIN PERFORM public.farm_media_metadata_save(photo,2,'{"source":"javascript:alert(1)"}');RAISE EXCEPTION 'FAIL: unsafe source accepted.';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 BEGIN PERFORM public.farm_media_metadata_save(photo,2,'{"focalPoint":{"x":null,"y":0}}');RAISE EXCEPTION 'FAIL: invalid focal point accepted.';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 IF public.farm_media_remove(cookie,photo) IS NOT TRUE THEN RAISE EXCEPTION 'FAIL: soft delete.';END IF;
 IF EXISTS(SELECT 1 FROM farm_private.media_cleanup c WHERE slot->>'original_path'=ANY(c.paths)) THEN RAISE EXCEPTION 'FAIL: recoverable bytes queued for deletion.';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.farm_media_versions WHERE id=version AND state='ready') THEN RAISE EXCEPTION 'FAIL: recoverable bytes quarantined.';END IF;
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(public.farm_media_trash_list()) t WHERE t->>'id'=photo::text) THEN RAISE EXCEPTION 'FAIL: deleted photo not discoverable.';END IF;
 result:=public.farm_media_restore(photo,3);
 IF result->>'revision'<>'4' OR result->>'restoredAs'<>'draft' THEN RAISE EXCEPTION 'FAIL: restore must create next private draft revision.';END IF;
 INSERT INTO public.farm_content(id,kind,payload) VALUES(content,'post','{}');
 INSERT INTO public.farm_revisions(id,content_id,revision,payload,actor_id) VALUES(rev,content,1,jsonb_build_object('mediaVersionId',version),actor);
 result:=public.farm_media_usage(photo);
 IF jsonb_array_length(result->'revisions')<>1 OR result->>'protected'<>'true' THEN RAISE EXCEPTION 'FAIL: retained revision usage missing.';END IF;
 BEGIN PERFORM public.farm_media_remove(cookie,photo);RAISE EXCEPTION 'FAIL: used photo removal accepted.';EXCEPTION WHEN foreign_key_violation THEN NULL;END;
 DELETE FROM public.farm_media_usages WHERE revision_id=rev;DELETE FROM public.farm_revisions WHERE id=rev;DELETE FROM public.farm_content WHERE id=content;
 INSERT INTO farm_private.releases(id,base_release_id,snapshot,created_at,actor_id,request_id,request_digest) VALUES(release,NULL,'{"version":1,"homepage":null,"posts":[],"withdrawnIds":[]}',clock_timestamp(),actor,gen_random_uuid(),repeat('a',64));
 INSERT INTO farm_private.release_media_refs(release_id,media_version_id) VALUES(release,version);
 result:=public.farm_media_usage(photo);
 IF jsonb_array_length(result->'releases')<>1 OR result->>'protected'<>'true' THEN RAISE EXCEPTION 'FAIL: retained release usage missing.';END IF;
 BEGIN PERFORM public.farm_media_remove(cookie,photo);RAISE EXCEPTION 'FAIL: release photo removal accepted.';EXCEPTION WHEN foreign_key_violation THEN NULL;END;
 result:=public.farm_media_retention_prepare();
 IF result->>'preparedOnly'<>'true' OR result->>'deleteEnabled'<>'false' OR NOT EXISTS(SELECT 1 FROM farm_private.media_retention_plans p WHERE p.id=(result->>'id')::uuid) THEN RAISE EXCEPTION 'FAIL: durable prepared-only retention plan.';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(result->'purgeMediaIds') t WHERE t=photo::text) THEN RAISE EXCEPTION 'FAIL: referenced photo listed for purge.';END IF;
 UPDATE farm_private.sessions SET revoked_at=clock_timestamp() WHERE user_id=actor;
 BEGIN PERFORM public.farm_media_metadata_read(photo);RAISE EXCEPTION 'FAIL: revoked session accepted.';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
END $$;
ROLLBACK;
SELECT 'PASS: metadata fields, technical preservation, CAS, user-session revocation, retained usage and recoverable draft restore; fixture rolled back.' AS result;
